  const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
  stateV2.voicePermissionGranted = true;
  // ponytail: 授权后立即释放轨道，避免与 SpeechRecognition 抢麦；浏览器会记住本页麦克风授权
