const WAKE_WORDS = ["小南小南", "你好小南", "唤醒小南"];
// 识别引擎常把轻声读成近音字，演示现场放宽唤醒匹配
const WAKE_FUZZY_RE_V2 = [
  /小[南难晓男楠][小]?[南难晓男楠]/,
  /你好.{0,2}小[南难晓男楠]/,
  /唤醒.{0,2}小[南难晓男楠]/,
  /(小[南难晓男楠]){2,}/
];
const MIC_AUDIO_CONSTRAINTS_V2 = {
  audio: {
    echoCancellation: true,
    noiseSuppression: false,
    autoGainControl: true,
    channelCount: 1
  }
};

function includesAnyV2(value, list = []) {
  return list.some((item) => value.includes(normalizeV2(item)));
}

function compactSpeechV2(text) {
  return normalizeV2(text).replace(/\s+/g, "");
}

function matchWakeWordV2(text) {
  const compact = compactSpeechV2(text);
  if (!compact) return false;
  if (includesAnyV2(compact, WAKE_WORDS)) return true;
  return WAKE_FUZZY_RE_V2.some((pattern) => pattern.test(compact));
}

function stripWakePrefixV2(text) {
  let command = compactSpeechV2(text);
  WAKE_WORDS.forEach((word) => {
    command = command.replaceAll(compactSpeechV2(word), "");
  });
  command = command
    .replace(/小[南难晓男楠]/g, "")
    .replace(/你好/g, "")
    .replace(/唤醒/g, "")
    .trim();
  return command;
}

function collectTranscriptsFromEventV2(event) {
  let interim = "";
  let finalChunk = "";
  const allTexts = [];
  for (let i = event.resultIndex; i < event.results.length; i += 1) {
    const result = event.results[i];
    for (let j = 0; j < result.length; j += 1) {
      const piece = String(result[j].transcript || "").trim();
      if (piece) allTexts.push(piece);
    }
    const primary = result[0]?.transcript || "";
    if (result.isFinal) finalChunk += primary;
    else interim += primary;
  }
  return {
    interim: interim.trim(),
    finalChunk: finalChunk.trim(),
    combined: (finalChunk + interim).trim(),
    allTexts
  };
}

