  if (!value || !matchWakeWordV2(value)) return;
  if (stripWakePrefixV2(value)) return;
  if (stateV2.awaitingCommand) return;
  stateV2.awaitingCommand = true;
  setStateV2("awake", 2800);
  showListenOverlayV2("已唤醒", "请说出你的业务指令...");
  setPetStatusV2("我在，你直接说业务需求就行");
  toastV2("海小南已唤醒，请继续说", "success", "语音唤醒");
  if (stateV2.awaitCommandTimer) window.clearTimeout(stateV2.awaitCommandTimer);
  stateV2.awaitCommandTimer = window.setTimeout(() => {
    stateV2.awaitingCommand = false;
    if (stateV2.standbyEnabled) {
      showListenOverlayV2("正在聆听...", "直接说「小南小南」唤醒我，或说出业务需求");
    } else {
      hideListenOverlayV2();
    }
  }, 12000);
}

function processActiveVoiceInterimV2(collected) {
  const display = (collected.finalChunk || collected.interim || collected.combined).trim();
  if (!display) return;
  showListenOverlayV2("正在聆听...", display);
  renderVoiceMeterV2(Math.min(1, 0.28 + display.length * 0.04), "text");
  setPetStatusV2("正在听：" + display);
  const wakeHit = collected.allTexts.some((piece) => matchWakeWordV2(piece)) || matchWakeWordV2(display);
  if (wakeHit) handleActiveVoiceWakeV2(display);
}

function processVoiceSpeechV2(text) {
  const value = normalizeV2(text);
  if (!value) return;
  const hasWakeWord = matchWakeWordV2(value);
  let command = hasWakeWord ? stripWakePrefixV2(value) : compactSpeechV2(value);
  if (hasWakeWord && !command) {
    handleActiveVoiceWakeV2(value);
    return;
  }
  if (command) {
    if (hasWakeWord || stateV2.awaitingCommand) {
      stateV2.awaitingCommand = false;
      if (stateV2.awaitCommandTimer) window.clearTimeout(stateV2.awaitCommandTimer);
    }
    if (hasWakeWord) setStateV2("awake", 1200);
    elsV2.mainInput.value = command;
    queueVoiceCommandV2(command, "voice");
  } else if (stateV2.awaitingCommand) {
    showListenOverlayV2("正在聆听...", "我没听清，请再说一次业务需求");
  }
}

