async function startActiveVoiceInstanceV2() {
  if (!stateV2.standbyEnabled) return;
  if (stateV2.textRecognition) return;
  await waitForRecognitionReleaseV2(200);
  if (!stateV2.standbyEnabled || elsV2.modalLayer.classList.contains("active")) return;
  const rec = createRecognitionV2({ continuous: true, interimResults: true });
  if (!rec) return;
  stateV2.textRecognition = rec;
  stateV2.textListening = true;
  let finalText = "";
  rec.onresult = (event) => {
    const collected = collectTranscriptsFromEventV2(event);
    finalText = collected.finalChunk || collected.combined;
    processActiveVoiceInterimV2(collected);
  };
  rec.onerror = (event) => {
    if (event.error === "no-speech" || event.error === "aborted") return;
    if (event.error === "audio-capture") releasePermissionStreamV2();
    const errMap = { "not-allowed": "请在浏览器设置中开启麦克风权限后重试。", "network": "语音识别需要网络连接。", "service-not-allowed": "语音服务暂不可用，请使用文本输入。" };
    toastV2(errMap[event.error] || "语音识别错误：" + event.error, "error", "语音识别");
    stopVoiceV2(false);
  };
  rec.onend = () => {
    stateV2.textRecognition = null;
    stateV2.textListening = false;
    const command = finalText.trim();
    if (command) {
      elsV2.mainInput.value = command;
      processVoiceSpeechV2(command);
    }
    if (stateV2.standbyEnabled) {
      refreshStandbyListenUiV2();
      window.setTimeout(() => startActiveVoiceInstanceV2(), 500);
    } else {
      elsV2.micTrigger.classList.remove("listening");
      resumePassiveAfterActiveVoiceV2();
    }
  };
  try {
    rec.start();
  } catch (e) {
    stateV2.textListening = false;
    stateV2.textRecognition = null;
    if (stateV2.standbyEnabled) {
      window.setTimeout(() => startActiveVoiceInstanceV2(), 800);
    } else {
      stopVoiceV2(false);
      toastV2("语音识别启动失败：" + e.message + "，请使用文本输入。", "error", "语音识别");
    }
  }
}

async function startStandbyVoiceV2() {
  if (stateV2.standbyEnabled) {
    refreshStandbyListenUiV2();
    await startActiveVoiceInstanceV2();
    return true;
  }
  if (!createRecognitionV2({ continuous: true, interimResults: true })) {
    toastV2("当前浏览器不支持语音识别，请使用文本输入。", "warning", "语音识别");
    return false;
  }
  pausePassiveForActiveVoiceV2(false);
  try {
    await prepareMicForSpeechRecognitionV2();
    await waitForRecognitionReleaseV2(320);
  } catch (e) {
    resumePassiveAfterActiveVoiceV2();
    return false;
  }
  stateV2.standbyEnabled = true;
  refreshStandbyListenUiV2();
  await startActiveVoiceInstanceV2();
  return true;
}

async function toggleVoiceV2() {
  if (stateV2.textListening || stateV2.standbyEnabled) {
    stopVoiceV2(true);
    return;
  }
  await startStandbyVoiceV2();
}

